function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // two characters
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // lines connecting characters
  ctx.beginPath();
  ctx.moveTo(W/4, H/2);
  ctx.lineTo(W - W/4 + 20 * Math.sin(t), H/2 + 20 * Math.cos(t));
  ctx.stroke();

  // lines around characters
  ctx.beginPath();
  ctx.arc(W/4, H/2, 40 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 40 + 10 * Math.cos(t), 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
